function validate(input) {
  const [{ Salaries = [] }] = input;
  const seen = new Set();
  for (const [company, employee, , salary] of Salaries) {
    if (company === null || employee === null) return 'Every row needs a company_id and an employee_id.';
    const key = `${company}/${employee}`;
    if (seen.has(key)) return `Employee ${employee} appears twice in company ${company}.`;
    seen.add(key);
    if (salary === null || salary < 0) return 'Every salary must be a non-negative number.';
  }
  return null;
}

