function generate(rand, size) {
  const names = ['Tony', 'Pronub', 'Tyrrox', 'Pam', 'Bassem', 'Hermione', 'Bocaben', 'Ognjen', 'Nyancat', 'Kim'];
  // Salaries near the bracket edges and amounts whose taxed value ends in .5 (50, 150, 10050).
  const pool = [0, 50, 150, 300, 999, 1000, 2200, 7777, 9999, 10000, 10001, 10050, 21300];
  const pick = list => list[Math.floor(rand() * list.length)];
  const companies = size === 'small' ? Math.floor(rand() * 4) : 250;
  const Salaries = [];
  for (let company = 1; company <= companies; company++) {
    const count = size === 'small' ? Math.floor(rand() * 4) : 8;
    const ids = [];
    while (ids.length < count) { const id = 1 + Math.floor(rand() * (size === 'small' ? 6 : 50)); if (!ids.includes(id)) ids.push(id); }
    for (const id of ids) {
      const salary = rand() < 0.7 ? pick(pool) : Math.floor(rand() * 25000);
      Salaries.push([company, id, pick(names), salary]);
    }
  }
  return [{ Salaries: Salaries.slice(0, size === 'small' ? 8 : 2000) }];
}
